def sort_numbers(numbers):
    result = []
    for num in numbers:
        result.append(num)
    for i in range(len(result)):
        for j in range(i + 1, len(result)):
            if result[i] > result[j]:
                temp = result[i]
                result[i] = result[j]
                result[j] = temp
    return result

