def almost_sorted(arr):
    n = len(arr)
    if n <= 1:
        return True
    sorted_arr = sorted(arr)
    mismatches = []
    for i in range(n):
        if arr[i] != sorted_arr[i]:
            mismatches.append(i)
    if len(mismatches) == 0:
        return True
    if len(mismatches) == 2:
        i, j = mismatches
        arr[i], arr[j] = arr[j], arr[i]
        return arr == sorted_arr
    return False

import heapq

scores = []

def update_leaderboard(new_score):
    if len(scores) < 100:
        heapq.heappush(scores, new_score)
    elif new_score > scores[0]:
        heapq.heapreplace(scores, new_score)
    # scores now holds the 100 largest values in ascending order
    return sorted(scores, reverse=True)

