def in_place_merge_sort(arr):
    _merge_sort(arr, 0, len(arr) - 1)

def _merge_sort(arr, left, right):
    if left < right:
        mid = (left + right) // 2
        _merge_sort(arr, left, mid)
        _merge_sort(arr, mid + 1, right)
        _merge(arr, left, mid, right)

def _merge(arr, left, mid, right):
    start = left
    end = mid + 1
    while start <= mid and end <= right:
        if arr[start] <= arr[end]:
            start += 1
        else:
            value = arr[end]
            arr[start:end + 1] = arr[start:end] + [value]
            start += 1
            mid += 1
            end += 1
    if start > mid:
        arr[start:end + 1] = arr[start:end]

def in_place_merge_sort(arr):
    _merge_sort(arr, 0, len(arr) - 1)
    return arr
